// EARLIEST path constants for the Electron main process.
//
// CONSTRAINTS:
//   - No business-module dependencies (no @shared / @main / business code).
//   - Only node built-ins and `electron` are allowed.
//   - Electron's `app.getPath()` is safe at this layer: it works at module
//     import time, before `app.whenReady()`. Verified by LoggerService which
//     constructs at module load and consumes LOGS_DIR through this file.
//
// CONSUMERS (all main-process bootstrap services):
//   - src/main/core/logger/LoggerService.ts          → uses LOGS_DIR
//   - src/main/data/bootConfig/BootConfigService.ts  → uses BOOT_CONFIG_PATH
//   - src/main/core/paths/pathRegistry.ts            → re-exposes LOGS_DIR as 'app.logs'
//   - src/main/core/preboot/userDataLocation.ts      → uses resolveDevUserDataPath

import os from 'node:os'
import path from 'node:path'

import { app } from 'electron'

// Duplicated from HOME_DIRNAME in @shared/utils/branding: this layer loads
// before app.whenReady() and may not import business modules (see CONSTRAINTS
// above). Change both together.
export const CHERRY_HOME_DIRNAME = '.the-boss'
export const CHERRY_HOME = path.join(os.homedir(), CHERRY_HOME_DIRNAME)
export const BOOT_CONFIG_PATH = path.join(CHERRY_HOME, 'boot-config.json')

const DEFAULT_DEV_USER_DATA_SUFFIX = 'Dev'

// The suffix is concatenated into directory names, so it must stay a single
// path component: separators, drive colons, and control/Windows-forbidden
// characters could normalize the dev directories back onto the packaged ones
// (e.g. `/../CherryStudio`). Trailing dots are rejected separately — Windows
// strips them, aliasing `CherryStudio.` (from suffix `.`) onto the packaged
// `CherryStudio` directory. Anything a filesystem accepts inside a single
// component — spaces, non-ASCII — stays valid.
const FORBIDDEN_DEV_USER_DATA_SUFFIX = /[\\/:*?"<>|]|\p{Cc}/u

/**
 * Dev-instance directory suffix (`CherryStudio` → `CherryStudioDev`),
 * overridable via CS_DEV_USER_DATA_SUFFIX.
 *
 * Blank values fall back to the default; a value that is not a single path
 * component aborts startup instead, because falling back would silently merge
 * a profile meant to be isolated into the shared `Dev` one. Throwing is also
 * the only way to report this: @logger is unavailable here, since
 * LoggerService consumes LOGS_DIR from this file.
 */
function resolveDevUserDataSuffix(): string {
  const configured = process.env.CS_DEV_USER_DATA_SUFFIX?.trim()
  if (!configured) return DEFAULT_DEV_USER_DATA_SUFFIX
  if (FORBIDDEN_DEV_USER_DATA_SUFFIX.test(configured) || configured.endsWith('.')) {
    throw new Error(
      `CS_DEV_USER_DATA_SUFFIX ${JSON.stringify(configured)} must be a single path component ` +
        '(no path separator, drive colon, Windows-reserved character or trailing dot).'
    )
  }
  return configured
}

/**
 * Dev-instance userData directory (`…/CherryStudio` → `…/CherryStudioDev`).
 * Applied by `core/preboot/userDataLocation.ts` and — on Windows and Linux,
 * where logs live inside userData — by the logs diversion below, so both
 * derive from one definition.
 */
export function resolveDevUserDataPath(): string {
  return app.getPath('userData') + resolveDevUserDataSuffix()
}

// Divert dev logs BEFORE the app.getPath('logs') call below caches Electron's
// default. That default never sees the dev userData suffix — on macOS it
// derives from the app *name* (~/Library/Logs/CherryStudio), elsewhere from
// the not-yet-suffixed userData — so without this a dev run would interleave
// its logs with a packaged install's.
if (!app.isPackaged) {
  app.setAppLogsPath(
    process.platform === 'darwin'
      ? app.getPath('logs') + resolveDevUserDataSuffix()
      : path.join(resolveDevUserDataPath(), 'logs')
  )
}

/**
 * Logs directory. Resolves to Electron's platform-standard location:
 *   - macOS:   ~/Library/Logs/<App>/
 *   - Windows: %APPDATA%/<App>/logs
 *   - Linux:   ~/.config/<App>/logs
 * where `<App>` carries the dev suffix in unpackaged runs (see above).
 *
 * Single source of truth — referenced by LoggerService directly and exposed
 * via pathRegistry as the `app.logs` key for `application.getPath()` consumers.
 */
export const LOGS_DIR = app.getPath('logs')

import fs from 'node:fs'
import path from 'node:path'

import { app } from 'electron'

import { loggerService } from '@logger'
import { resolveDevUserDataPath } from '@main/core/paths/constants'
import { isLinux, isPortable, isWin } from '@main/core/platform'
import { bootConfigService } from '@main/data/bootConfig'
import { PRODUCT_DIRNAME } from '@shared/utils/branding'

const logger = loggerService.withContext('Preboot')

/** Upstream's userData directory name, detected only to report it, never adopted. */
const LEGACY_UPSTREAM_DIRNAME = 'CherryStudio'

/**
 * "userData" in this module means Electron's complete OS-level userData
 * directory, including user content, Chromium state, and — on Windows and
 * Linux — application logs (macOS keeps logs in ~/Library/Logs instead).
 */

export function getNormalizedExecutablePath(): string {
  if (isLinux && process.env.APPIMAGE) {
    return path.join(path.dirname(process.env.APPIMAGE), 'cherry-studio.appimage')
  }
  if (isWin && isPortable) {
    return path.join(process.env.PORTABLE_EXECUTABLE_DIR || '', 'cherry-studio-portable.exe')
  }
  return app.getPath('exe')
}

export function canonicalizeUserDataPath(userDataPath: string): string {
  if (!path.isAbsolute(userDataPath)) {
    throw new Error(`userData path must be absolute: ${userDataPath}`)
  }
  return path.normalize(userDataPath)
}

/**
 * Resolve Electron's userData directory before the path registry is frozen.
 * Pending relocation is deliberately not executed here: after the source path
 * is resolved and its single-instance lock is acquired, the
 * `services/userDataRelocation` domain owns validation, copy/switch, commit,
 * progress UI, and relaunch (`runUserDataRelocation()` called from main.ts).
 * The `app.user_data_path` mapping read below is written by that domain's
 * commit step.
 *
 * Electron derives sessionData lazily from userData when no explicit
 * sessionData path was set. Keeping this setPath call before app.whenReady()
 * therefore carries Cookies, Local Storage, IndexedDB, and other Chromium
 * storage to the selected directory as well.
 */
export function resolveUserDataLocation(): void {
  if (!app.isPackaged) {
    const devPath = resolveDevUserDataPath()
    app.setPath('userData', devPath)
    logger.info('userData set with dev suffix', { devPath })
    return
  }

  const exe = getNormalizedExecutablePath()
  const resolved = bootConfigService.get('app.user_data_path')?.[exe]
  if (resolved && isUsableDataDir(resolved)) {
    app.setPath('userData', resolved)
    logger.info('userData set from BootConfig', { exe, resolved })
    return
  }

  if (isPortable) {
    const portableDir = process.env.PORTABLE_EXECUTABLE_DIR
    const portablePath = path.join(portableDir || app.getPath('exe'), 'data')
    app.setPath('userData', portablePath)
    logger.info('userData set for portable build', { portablePath })
    return
  }

  const brandedPath = path.join(app.getPath('appData'), PRODUCT_DIRNAME)
  app.setPath('userData', brandedPath)
  logger.info('userData set from branding', { brandedPath })
  warnOnUnadoptedLegacyDataDir(brandedPath)
}

/**
 * This fork deliberately starts with an empty profile rather than adopting an
 * upstream Cherry Studio one: the directory layouts are only coincidentally
 * compatible, and silently importing another app's data is worse than starting
 * clean. Log it so an operator can find the old directory instead of concluding
 * their data vanished.
 */
function warnOnUnadoptedLegacyDataDir(brandedPath: string): void {
  const legacyPath = path.join(app.getPath('appData'), LEGACY_UPSTREAM_DIRNAME)
  if (legacyPath === brandedPath || !isUsableDataDir(legacyPath)) return

  logger.warn('Legacy Cherry Studio data directory found and deliberately not adopted', {
    legacyPath,
    brandedPath
  })
}

/**
 * A usable data directory must be readable, writable, and searchable. This is
 * shared with v1-to-v2 migration path selection so both startup paths enforce
 * the same filesystem bar.
 */
export function isUsableDataDir(value: string): boolean {
  try {
    if (!fs.statSync(value).isDirectory()) return false
    fs.accessSync(value, fs.constants.R_OK | fs.constants.W_OK | fs.constants.X_OK)
    return true
  } catch {
    return false
  }
}

